import itertools

def frange(start, stop, step):
    vals = []
    v = start
    if step > 0:
        while v <= stop:
            vals.append(v)
            v += step
    else:
        while v >= stop:
            vals.append(v)
            v += step
    return vals

def expand_commands(commands, opts):
    # build list of parameter dicts
    param_lists = []

    # from -L
    for var, vals in opts['parameter_list']:
        param_lists.append([{var: v.strip()} for v in vals.split(',')])

    # from -P
    for i, (var, min_val, max_val) in enumerate(opts['parameter_scan']):
        min_v = float(min_val)
        max_v = float(max_val)
        step = 1.0
        if i < len(opts['parameter_step_size']):
            step = float(opts['parameter_step_size'][i])

        vals = frange(min_v, max_v, step)
        # Format as int if it has no fractional part
        formatted_vals = []
        for v in vals:
            if v.is_integer():
                formatted_vals.append(str(int(v)))
            else:
                formatted_vals.append(str(v))
        param_lists.append([{var: v} for v in formatted_vals])

    if not param_lists:
        return commands

    combinations = list(itertools.product(*param_lists))
    expanded_cmds = []
    for cmd in commands:
        for combo in combinations:
