            else:
                needed = opts['min_runs']
            if opts['max_runs']: needed = min(needed, opts['max_runs'])
            runs = needed

        for _ in range(len(times), runs):
            if prepare_cmd:
                run_command(prepare_cmd, opts['shell'], opts['show_output'])
            res = run_command(cmd, opts['shell'], opts['show_output'])
            if conclude_cmd:
                run_command(conclude_cmd, opts['shell'], opts['show_output'])

            real_time = max(0.0, res['real'] - shell_overhead)
            if res['code'] != 0 and not opts['ignore_failure']:
                print(f"Error: Command terminated with non-zero exit code {res['code']} in the first benchmark run. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.", file=sys.stderr)
                sys.exit(1)

            times.append(real_time)
            users.append(max(0.0, res['user']))
            syss.append(max(0.0, res['sys']))
            codes.append(res['code'])

        mean = statistics.mean(times)
        stdev = statistics.stdev(times) if len(times) > 1 else 0.0
        min_val = min(times)
        max_val = max(times)

        user_mean = statistics.mean(users)
        sys_mean = statistics.mean(syss)

        mean_str = format_time(mean, opts['time_unit'])
        unit = mean_str.split()[-1]

        std_str = format_time(stdev, unit, fixed_unit=True)
        user_str = format_time(user_mean, unit, fixed_unit=True)
        sys_str = format_time(sys_mean, unit, fixed_unit=True)
        min_str = format_time(min_val, unit, fixed_unit=True)
        max_str = format_time(max_val, unit, fixed_unit=True)

        print(f"  Time (mean ± σ):     {mean_str} ± {std_str}    [User: {user_str}, System: {sys_str}]")
        print(f"  Range (min … max):   {min_str} … {max_str}    {runs} runs")
        print(" ")

        results.append({
            'command': cmd,
            'mean': mean,
            'stddev': stdev,
            'median': statistics.median(times),
            'user': user_mean,
            'system': sys_mean,
            'min': min_val,
            'max': max_val,
            'times': times,
            'exit_codes': codes,
            'memory_usage_byte': [0]*len(times)
        })

    if opts['cleanup']:
        run_command(opts['cleanup'], opts['shell'], opts['show_output'])

    if len(results) > 1:
        results.sort(key=lambda x: x['mean'])
        print("Summary")
        print(f"  {results[0]['command']} ran")
        for res in results[1:]:
            ratio = res['mean'] / results[0]['mean'] if results[0]['mean'] > 0 else float('inf')
            print(f"   {ratio:>5.2f} ± 0.00 times faster than {res['command']}")

    if opts['export_json']:
        with open(opts['export_json'], 'w') as f:
            json.dump({"results": results}, f, indent=2)

    if opts['export_csv']:
        with open(opts['export_csv'], 'w') as f:
            f.write("command,mean,stddev,median,user,system,min,max\n")
            for res in results:
                f.write(f"{res['command']},{res['mean']},{res['stddev']},{res['median']},{res['user']},{res['system']},{res['min']},{res['max']}\n")

    if opts['export_asciidoc']:
        with open(opts['export_asciidoc'], 'w') as f:
            f.write("[cols=\"<,>,>,>,>\"]\n|===\n")
            f.write(f"| Command \n| Mean [{unit}] \n| Min [{unit}] \n| Max [{unit}] \n| Relative \n\n")
            for i, res in enumerate(results):
                mean_str = format_time(res['mean'], unit, fixed_unit=True).split()[0].strip()
                stdev_str = format_time(res['stddev'], unit, fixed_unit=True).split()[0].strip()
                min_str = format_time(res['min'], unit, fixed_unit=True).split()[0].strip()
                max_str = format_time(res['max'], unit, fixed_unit=True).split()[0].strip()
                if i == 0:
                    rel = "1.00 "
                else:
                    ratio = res['mean'] / results[0]['mean'] if results[0]['mean'] > 0 else float('inf')
                    rel = f"{ratio:.2f} ± 0.00 "
                f.write(f"| `{res['command']}` \n| {mean_str} ± {stdev_str} \n| {min_str} \n| {max_str} \n| {rel}\n")
            f.write("|===\n")

    if opts['export_orgmode']:
        with open(opts['export_orgmode'], 'w') as f:
            f.write(f"| Command  |  Mean [{unit}] |  Min [{unit}] |  Max [{unit}] |  Relative |\n")
            f.write("|--+--+--+--+--|\n")
            for i, res in enumerate(results):
                mean_str = format_time(res['mean'], unit, fixed_unit=True).split()[0].strip()
                stdev_str = format_time(res['stddev'], unit, fixed_unit=True).split()[0].strip()
                min_str = format_time(res['min'], unit, fixed_unit=True).split()[0].strip()
                max_str = format_time(res['max'], unit, fixed_unit=True).split()[0].strip()
                if i == 0:
                    rel = "1.00"
                else:
                    ratio = res['mean'] / results[0]['mean'] if results[0]['mean'] > 0 else float('inf')
                    rel = f"{ratio:.2f} ± 0.00"
                f.write(f"| ={res['command']}=  |  {mean_str} ± {stdev_str} |  {min_str} |  {max_str} |  {rel} |\n")

    if opts['export_markdown']:
        with open(opts['export_markdown'], 'w') as f:
            f.write(f"| Command | Mean [{unit}] | Min [{unit}] | Max [{unit}] | Relative |\n")
            f.write(f"|:---|---:|---:|---:|---:|\n")
            for i, res in enumerate(results):
                mean_str = format_time(res['mean'], unit, fixed_unit=True).split()[0].strip()
                stdev_str = format_time(res['stddev'], unit, fixed_unit=True).split()[0].strip()
                min_str = format_time(res['min'], unit, fixed_unit=True).split()[0].strip()
                max_str = format_time(res['max'], unit, fixed_unit=True).split()[0].strip()
                if i == 0:
                    rel = "1.00"
                else:
                    ratio = res['mean'] / results[0]['mean'] if results[0]['mean'] > 0 else float('inf')
                    rel = f"{ratio:.2f} ± 0.00"
                f.write(f"| `{res['command']}` | {mean_str} ± {stdev_str} | {min_str} | {max_str} | {rel} |\n")

if __name__ == "__main__":
    main()
